#!/usr/bin/env bash
# totalsegmri-pancreas: combined (all source contrasts) table via the shared combined_modality_summary.py (never hand-compute tables / p-values). Configs are GENERATED by 06_05_write_configs.sh.
#   bash 06_04_combined_modality_summary.sh [configs/totalsegmri-pancreas_combined_01_results.yaml]
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "${HERE}/../00_utils/env.sh"; cd "${PROJECT_ROOT}"
CFG="${1:-configs/totalsegmri-pancreas_combined_01_results.yaml}"; [[ "$CFG" != /* ]] && CFG="${HERE}/${CFG}"
.venv/bin/python benchmark/00_commun_scripts/00_03_evaluate/combined_modality_summary.py "${CFG}"
